#include "image_core.c"
#include <stdio.h>
#include <stdlib.h>
static unsigned checks;
static size_t peak_bytes,peak_success_reserved,peak_success_large,peak_refusal;
#define CHECK(v) do { ++checks; if(!(v)){fprintf(stderr,"FAIL %d: %s\n",__LINE__,#v);exit(1);} } while(0)
typedef struct { size_t live,peak,calls; long fail_at; int persistent; } Memory;
typedef union { size_t size; long double alignment; } Header;
static void *allocate(void *ctx,size_t bytes){Memory*m=ctx;size_t call=m->calls++;Header*h;if((m->fail_at>=0&&(call==(size_t)m->fail_at||(m->persistent&&call>=(size_t)m->fail_at)))||bytes>18u*1024u*1024u-m->live)return 0;h=malloc(sizeof(*h)+bytes);if(!h)return 0;h->size=bytes;m->live+=bytes;if(m->live>m->peak)m->peak=m->live;return h+1;}
static void release(void *ctx,void*p){Memory*m=ctx;Header*h;if(!p)return;h=(Header*)p-1;CHECK(h->size<=m->live);m->live-=h->size;free(h);}
static void setup(IEDoc*d,Memory*m,int w,int h){memset(m,0,sizeof(*m));m->fail_at=-1;CHECK(ie_init(d,allocate,release,m,w,h));CHECK(ie_new(d,w,h,IE_RGBA(70,130,180,255)));}
static void finish(IEDoc*d,Memory*m){if(m->peak>peak_bytes)peak_bytes=m->peak;ie_destroy(d);CHECK(!m->live);}
static uint64_t digest(const IEDoc*d){size_t i,n=(size_t)d->current.width*d->current.height;uint64_t h=1469598103934665603ull;for(i=0;i<n;i++){h^=d->current.layers[0].pixels[i];h*=1099511628211ull;h^=d->current.selection_mask?d->current.selection_mask[i]:0;h*=1099511628211ull;}return h;}
static IEFillOptions options(void){IEFillOptions f={0};f.kind=IE_FILL_RELIEF;f.region=IE_FILL_SELECTION;f.opacity=f.density=100;f.scale=12;f.relief_profile=IE_RELIEF_CIRCULAR;f.relief_unit=IE_RELIEF_PIXELS;f.relief_extent=12;f.relief_height=16;f.relief_azimuth=225;f.relief_intensity=100;f.foreground=IE_RGBA(30,125,220,255);return f;}
static int complete(IEJob*j){unsigned count=0,prev=0;int result;CHECK(j);while(!(result=ie_job_step(j,64))){unsigned p=ie_job_progress(j);CHECK(p>=prev&&p<=100);prev=p;CHECK(++count<100000);}CHECK(ie_job_progress(j)==100);ie_job_destroy(j);return result;}
static void shaped_mask(IEDoc*d){int x,y,w=d->current.width,h=d->current.height;d->current.selection_mask=allocate(d->memory_context,(size_t)w*h);CHECK(d->current.selection_mask);d->current.selection=(IERect){0,0,w,h,1};for(y=0;y<h;y++)for(x=0;x<w;x++){int outer=x>=2&&y>=2&&x<w-2&&y<h-2,hole=x>=w/3&&x<2*w/3&&y>=h/3&&y<2*h/3,notch=x>w*3/4&&y<h/2;d->current.selection_mask[(size_t)y*w+x]=(uint8_t)(outer&&!hole&&!notch?255:0);}}
static unsigned oracle(const uint8_t*m,int w,int h,int x,int y){int xx,yy,border=mini(mini(x+1,w-x),mini(y+1,h-y));unsigned best=(unsigned)border*border;if(!m[(size_t)y*w+x])return 0;for(yy=0;yy<h;yy++)for(xx=0;xx<w;xx++)if(!m[(size_t)yy*w+xx]){int dx=xx-x,dy=yy-y;unsigned cost=(unsigned)(dx*dx+dy*dy);if(cost<best)best=cost;}return relief_sqrt64((uint64_t)best*256);}
static int field_distance(const IEJob*j,int x,int y){x-=j->minx;y-=j->miny;if(x<0||y<0||x>=j->relief_w||y>=j->relief_h)return 0;return j->relief[(size_t)y*j->relief_w+x];}
static void test_distance(void){IEDoc d;Memory m;IEJob*j;IEFillOptions f=options();int x,y;uint64_t initial;setup(&d,&m,43,37);shaped_mask(&d);initial=digest(&d);j=ie_fill_start(&d,&f);CHECK(j);while(j->stage!=JOB_RELIEF_HEIGHT){CHECK(ie_job_step(j,1)==0);}for(y=0;y<37;y++)for(x=0;x<43;x++)CHECK(field_distance(j,x,y)==(int)oracle(j->mask,43,37,x,y));CHECK(digest(&d)==initial);ie_job_cancel(j);ie_job_destroy(j);CHECK(digest(&d)==initial);finish(&d,&m);}
static void test_lighting(void){IEDoc d;Memory m;IEFillOptions f=options();uint32_t results[4][47*41];int direction,x,y;setup(&d,&m,47,41);for(direction=0;direction<4;direction++){CHECK(ie_new(&d,47,41,IE_RGBA(30,125,220,255)));ie_select(&d,3,3,43,37);f.relief_azimuth=(225+90*direction)%360;CHECK(complete(ie_fill_start(&d,&f))==1);memcpy(results[direction],d.current.layers[0].pixels,sizeof(results[0]));CHECK(results[direction][20*47+23]==f.foreground);}
 for(y=0;y<41;y++)for(x=0;x<47;x++){CHECK(results[0][y*47+x]==results[1][y*47+46-x]);CHECK(results[0][y*47+x]==results[3][(40-y)*47+x]);CHECK(results[0][y*47+x]==results[2][(40-y)*47+46-x]);}
 CHECK(results[0][4*47+4]!=results[0][36*47+42]);finish(&d,&m);}
static void test_alpha(void){IEDoc d;Memory m;IEFillOptions f=options();int feather,profile;size_t i;uint32_t before[35*31];for(feather=-6;feather<=6;feather+=6)for(profile=0;profile<3;profile++){setup(&d,&m,35,31);shaped_mask(&d);for(i=0;i<35*31;i++){unsigned alpha=(unsigned)(i%7)*37;if(d.current.selection_mask[i])d.current.selection_mask[i]=(uint8_t)(alpha?alpha:1);d.current.layers[0].pixels[i]=before[i]=IE_RGBA(9,13,22,(i%5)*61);}
 f.feather=feather;f.foreground=IE_RGBA(35,101,193,107);f.density=73;f.opacity=67;f.relief_profile=profile;CHECK(complete(ie_fill_start(&d,&f))==1);for(i=0;i<35*31;i++){uint32_t after=d.current.layers[0].pixels[i];CHECK((before[i]>>24)==(after>>24));if(!(before[i]>>24)||!d.current.selection_mask[i])CHECK(before[i]==after);}finish(&d,&m);}}
static void test_cancel_undo(void){IEDoc d;Memory m;IEFillOptions f=options();IEJob*j;uint64_t before,painted;setup(&d,&m,64,48);shaped_mask(&d);before=digest(&d);j=ie_fill_start(&d,&f);CHECK(j);while(j->stage!=JOB_PAINT)CHECK(ie_job_step(j,1)==0);CHECK(ie_job_step(j,64*12)==0);CHECK(digest(&d)!=before);ie_job_cancel(j);ie_job_destroy(j);CHECK(digest(&d)==before);CHECK(complete(ie_fill_start(&d,&f))==1);painted=digest(&d);CHECK(painted!=before);CHECK(ie_undo(&d));CHECK(digest(&d)==before);CHECK(ie_redo(&d));CHECK(digest(&d)==painted);finish(&d,&m);}
static void test_failures(void){int persistent,fail;for(persistent=0;persistent<2;persistent++)for(fail=0;fail<24;fail++){IEDoc d;Memory m;IEFillOptions f=options();IEJob*j;uint64_t before;int r=0;setup(&d,&m,40,30);shaped_mask(&d);before=digest(&d);f.feather=-4;m.fail_at=(long)m.calls+fail;m.persistent=persistent;j=ie_fill_start(&d,&f);if(j){while(!(r=ie_job_step(j,120)));ie_job_destroy(j);}m.fail_at=-1;if(!j||r<0)CHECK(digest(&d)==before);else {CHECK(ie_undo(&d));CHECK(digest(&d)==before);}finish(&d,&m);}}
static void test_float_interaction(void){IEDoc d;Memory m;IEFillOptions f=options();IEJob*j;uint64_t original,moved;int pass;size_t i;setup(&d,&m,71,55);shaped_mask(&d);for(i=0;i<71*55;i++)d.current.layers[0].pixels[i]=IE_RGBA(i%251,(i*7)%253,(i*13)%255,(i%4)*85);original=digest(&d);
 for(pass=0;pass<2;pass++){CHECK(ie_translate_selection(&d,9,4));moved=digest(&d);CHECK(d.current.floating);j=ie_fill_start(&d,&f);CHECK(j);while(j->stage!=JOB_PAINT)CHECK(ie_job_step(j,1)==0);CHECK(ie_job_step(j,71*12)==0);if(pass==0){ie_job_cancel(j);ie_job_destroy(j);}else{CHECK(complete(j)==1);CHECK(ie_undo(&d));}CHECK(digest(&d)==moved);CHECK(d.current.floating);CHECK(ie_translate_selection(&d,85,-70));CHECK(ie_translate_selection(&d,-94,66));CHECK(digest(&d)==original);}
 {IESelectionOptions q={0};q.method=IE_SELECT_RECT;q.x0=4;q.y0=5;q.x1=40;q.y1=35;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(!d.current.floating);}finish(&d,&m);}
static void test_small_large(void){IEDoc d;Memory m;IEFillOptions f=options();setup(&d,&m,1,1);f.scale=64;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(d.current.layers[0].pixels[0]>>24==255);finish(&d,&m);setup(&d,&m,1024,768);ie_select(&d,30,30,990,730);f.scale=24;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(m.peak<11u*1024u*1024u);peak_success_large=m.peak;finish(&d,&m);}
static void until_stage(IEJob*j,int stage){unsigned count=0;CHECK(j);while(j->stage!=stage){CHECK(ie_job_step(j,1)==0);CHECK(++count<100000);} }
static void test_profiles(void){IEDoc d;Memory m;IEFillOptions f=options();IEJob*j;int profile,x;uint16_t full[101];setup(&d,&m,101,101);f.relief_unit=IE_RELIEF_PERCENT;f.relief_extent=100;f.relief_height=32;
 for(profile=0;profile<3;profile++){f.relief_profile=profile;j=ie_fill_start(&d,&f);until_stage(j,JOB_PAINT);CHECK(job_relief_height(j,50,50)==32*64);for(x=1;x<50;x++){int previous=job_relief_height(j,x-1,50),value=job_relief_height(j,x,50);CHECK(value>=previous);if(profile==IE_RELIEF_LINEAR)CHECK(value>previous);if(profile==IE_RELIEF_EXTRUDE)CHECK(value==32*64);}for(x=0;x<101;x++)CHECK(job_relief_height(j,x,50)==job_relief_height(j,100-x,50));if(profile==IE_RELIEF_LINEAR)for(x=0;x<101;x++)full[x]=(uint16_t)job_relief_height(j,x,50);ie_job_cancel(j);ie_job_destroy(j);}
 f.relief_profile=IE_RELIEF_LINEAR;f.relief_unit=IE_RELIEF_PIXELS;f.relief_extent=51;j=ie_fill_start(&d,&f);until_stage(j,JOB_PAINT);for(x=0;x<101;x++)CHECK(job_relief_height(j,x,50)==full[x]);ie_job_destroy(j);
 f.relief_unit=IE_RELIEF_PERCENT;f.relief_extent=50;j=ie_fill_start(&d,&f);until_stage(j,JOB_PAINT);CHECK(job_relief_height(j,30,50)==job_relief_height(j,50,50));CHECK(job_relief_height(j,10,50)<job_relief_height(j,30,50));ie_job_destroy(j);
 f.relief_extent=100;f.relief_height=-32;j=ie_fill_start(&d,&f);until_stage(j,JOB_PAINT);for(x=0;x<101;x++)CHECK(job_relief_height(j,x,50)==-(int)full[x]);ie_job_destroy(j);finish(&d,&m);}
static void test_random_distances(void){unsigned seed=12345;int pass;for(pass=0;pass<10;pass++){IEDoc d;Memory m;IEJob*j;IEFillOptions f=options();int x,y,w=1+pass*3,h=1+pass*2;setup(&d,&m,w,h);d.current.selection_mask=allocate(&m,(size_t)w*h);CHECK(d.current.selection_mask);d.current.selection=(IERect){0,0,w,h,1};for(y=0;y<h;y++)for(x=0;x<w;x++){seed=seed*1664525u+1013904223u;d.current.selection_mask[(size_t)y*w+x]=(seed>>28)<3?0:255;}d.current.selection_mask[0]=255;j=ie_fill_start(&d,&f);until_stage(j,JOB_RELIEF_HEIGHT);for(y=0;y<h;y++)for(x=0;x<w;x++)CHECK(field_distance(j,x,y)==(int)oracle(j->mask,w,h,x,y));ie_job_destroy(j);finish(&d,&m);}}
static void test_components(void){IEDoc d;Memory m;IEJob*j;IEFillOptions f=options();int x,y;setup(&d,&m,101,61);d.current.selection_mask=allocate(&m,101*61);CHECK(d.current.selection_mask);d.current.selection=(IERect){0,0,101,61,1};for(y=0;y<61;y++)for(x=0;x<101;x++){int large=x>=3&&x<=43&&y>=10&&y<=50;int narrow=x>=70&&x<=80&&y>=20&&y<=40;d.current.selection_mask[y*101+x]=(uint8_t)(large||narrow?255:0);}f.relief_profile=IE_RELIEF_LINEAR;f.relief_unit=IE_RELIEF_PERCENT;f.relief_extent=100;f.relief_height=100;j=ie_fill_start(&d,&f);until_stage(j,JOB_PAINT);CHECK(job_relief_height(j,23,30)==6400);CHECK(job_relief_height(j,75,30)>0&&job_relief_height(j,75,30)<6400);CHECK(job_relief_height(j,55,30)==0);ie_job_destroy(j);finish(&d,&m);}
static void test_controls(void){IEDoc d;Memory m;IEFillOptions f=options();uint32_t colors[3][41*41];uint64_t before;int azimuth,pass;size_t i;setup(&d,&m,41,41);ie_select(&d,2,2,38,38);before=digest(&d);f.relief_intensity=0;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(digest(&d)==before);CHECK(!d.undo_count);f.relief_intensity=100;f.relief_height=0;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(digest(&d)==before);CHECK(!d.undo_count);f.relief_height=16;
 for(pass=0;pass<3;pass++){f.relief_azimuth=pass==0?359:pass==1?0:360;CHECK(complete(ie_fill_start(&d,&f))==1);memcpy(colors[pass],d.current.layers[0].pixels,sizeof(colors[pass]));CHECK(ie_undo(&d));CHECK(digest(&d)==before);}for(i=0;i<41*41;i++){unsigned k;CHECK(colors[1][i]==colors[2][i]);for(k=0;k<24;k+=8)CHECK(absi((int)((colors[0][i]>>k)&255)-(int)((colors[1][i]>>k)&255))<=4);}
 for(azimuth=0;azimuth<360;azimuth+=7){f.relief_azimuth=azimuth;f.relief_height=azimuth&1?256:-256;f.relief_intensity=200;f.relief_profile=IE_RELIEF_EXTRUDE;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(ie_undo(&d));CHECK(digest(&d)==before);}finish(&d,&m);}
static void test_skinny(void){int pass;for(pass=0;pass<4;pass++){IEDoc d;Memory m;IEFillOptions f=options();IEJob*j;int w=pass<2?8192:(pass==2?1:64),h=pass<2?(pass==0?1:64):8192;setup(&d,&m,w,h);f.relief_extent=100;f.relief_unit=IE_RELIEF_PERCENT;f.relief_height=pass&1?-256:256;f.relief_intensity=200;j=ie_fill_start(&d,&f);CHECK(complete(j)==1);CHECK(ie_undo(&d));finish(&d,&m);}}
static void test_paint_cancels(void){int stage;for(stage=JOB_GENERATE;stage<=JOB_PAINT;stage++){IEDoc d;Memory m;IEFillOptions f=options();IEJob*j;uint64_t before;setup(&d,&m,27,23);shaped_mask(&d);f.feather=-2;before=digest(&d);j=ie_fill_start(&d,&f);CHECK(j);if(stage!=JOB_FLOOD&&stage!=JOB_CLEAN){until_stage(j,stage);CHECK(ie_job_step(j,1)==0);}ie_job_destroy(j);CHECK(digest(&d)==before);finish(&d,&m);}}
static void test_budget(void){IEDoc d;Memory m;IEFillOptions f=options();IEJob*j;uint64_t before;void*view;int result=0;setup(&d,&m,1100,610);view=allocate(&m,2u*1024u*1024u);CHECK(view);shaped_mask(&d);f.relief_extent=100;f.relief_unit=IE_RELIEF_PERCENT;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(m.peak<18u*1024u*1024u);peak_success_reserved=m.peak;release(&m,view);finish(&d,&m);
 setup(&d,&m,2000,1000);view=allocate(&m,2u*1024u*1024u);CHECK(view);before=digest(&d);j=ie_fill_start(&d,&f);if(j){while(!(result=ie_job_step(j,4096)));ie_job_destroy(j);}CHECK(!j||result<0);CHECK(digest(&d)==before);CHECK(m.peak<=18u*1024u*1024u);peak_refusal=m.peak;release(&m,view);finish(&d,&m);}
static void preview(const char*path){
 const int width=600,height=400,side=200;uint32_t*sheet=malloc((size_t)width*height*sizeof(*sheet));int profile,sign,x,y;FILE*out;CHECK(sheet);
 for(sign=0;sign<2;sign++)for(profile=0;profile<3;profile++){
  IEDoc d;Memory m;IEFillOptions f=options();setup(&d,&m,side,side);d.current.selection_mask=allocate(&m,(size_t)side*side);CHECK(d.current.selection_mask);d.current.selection=(IERect){0,0,side,side,1};
  for(y=0;y<side;y++)for(x=0;x<side;x++){int dx=x-99,dy=y-99,disk=dx*dx+dy*dy<76*76;size_t at=(size_t)y*side+x;d.current.selection_mask[at]=(uint8_t)(disk?255:0);d.current.layers[0].pixels[at]=disk?IE_RGBA(35+x/5,130,190,255):IE_RGBA(235,239,243,255);}
  f.relief_profile=profile;f.relief_extent=100;f.relief_unit=IE_RELIEF_PERCENT;f.relief_height=sign?-45:45;CHECK(complete(ie_fill_start(&d,&f))==1);
  for(y=0;y<side;y++)for(x=0;x<side;x++)sheet[(size_t)(sign*side+y)*width+profile*side+x]=d.current.layers[0].pixels[(size_t)y*side+x];
  finish(&d,&m);
 }
 out=fopen(path,"wb");CHECK(out);fprintf(out,"P6\n%d %d\n255\n",width,height);for(y=0;y<height;y++)for(x=0;x<width;x++){uint32_t c=sheet[(size_t)y*width+x];uint8_t rgb[3]={(uint8_t)c,(uint8_t)(c>>8),(uint8_t)(c>>16)};if(fwrite(rgb,1,3,out)!=3){fprintf(stderr,"preview write failed\n");exit(1);}}CHECK(fclose(out)==0);free(sheet);
}
int main(int argc,char**argv){test_distance();test_random_distances();test_profiles();test_components();test_controls();test_skinny();test_paint_cancels();test_budget();test_lighting();test_alpha();test_cancel_undo();test_failures();test_float_interaction();test_small_large();if(argc>1)preview(argv[1]);printf("{\"checks\":%u,\"allocationFailureScenarios\":48,\"peakModelBytes\":%zu,\"success1024x768Bytes\":%zu,\"success1100x610With2MiBViewBytes\":%zu,\"refused2000x1000PeakBytes\":%zu,\"passed\":true}\n",checks,peak_bytes,peak_success_large,peak_success_reserved,peak_refusal);return 0;}
